let saving=false,pdfDispose=null,baseUpdated=false,pdfRequestGeneration=0;
async function original(id){if(!id){toast('No hay un original vinculado');return;}const request=++pdfRequestGeneration,file=await bridge.request('/documentos/'+id,undefined,true);if(!dead&&request===pdfRequestGeneration)await viewPDF(await file.arrayBuffer(),state.documents.find(d=>d.id===id)?.name||'Resumen',id);}
