async function refresh(keepForm=false){const data=await bridge.request();if(dead)return;state=M.hydrate(data.state,data.state.ownerUid);if(keepForm&&(document.getElementById('dialog').open||stage))baseUpdated=true;else if(!keepForm)render();}
async function mutate(type,data){
 if(dead||!bridge)throw Error('El espacio privado está cerrado');
 const candidate={type,data,revision:state.revision};
 if(pendingCommand){if(JSON.stringify({type:pendingCommand.type,data:pendingCommand.data})!==JSON.stringify({type,data}))throw Error('Primero reintentá la operación pendiente sin cambiar el formulario, o actualizá la base para resolverla.');}
 else pendingCommand={id:crypto.randomUUID(),...candidate};
 try{const result=await bridge.request('/guardar',pendingCommand);if(dead)return;state=M.hydrate(result.state,result.state.ownerUid);pendingCommand=null;baseUpdated=false;return result;}
 catch(e){if(e.status===400||e.status===403||e.status===404||e.status===409||e.status===413)pendingCommand=null;throw e;}
}
